public class Foo {
    public boolean foo(Object foo, boolean a, boolean b) {
        if (foo instanceof Foo) { // foo instanceof Foo && (a || b)
            return a || b;
        } else {
            return false;
        }
        if (foo instanceof Foo) { // !(foo instanceof Foo) || a
            return a;
        } else {
            return true;
        }
        if (foo instanceof Foo) { // foo instanceof Foo && a
            return a;
        } else {
            return false;
        }
        if (a || b) { // (a || b) && a
            return a;
        } else {
            return false;
        }
        if (foo instanceof Foo) { // !(foo instanceof Foo) && a;
            return false;
        } else {
            return a;
        }
    }
}

public class Foo {
    public boolean foo(Object foo, boolean a, boolean b) {
        if (foo == null) { // foo != null || a
            return a;
        } else {
            return true;
        }
        if (!(foo instanceof String)) { // foo instanceof String || a
            return a;
        } else {
            return true;
        }
    }
}

public class Foo {
    public boolean foo(Object foo, boolean a, boolean b) {
        if (foo instanceof Foo) { // foo instanceof Foo && (a || b) - parens are required so not triggered
            return (a || b);
        } else {
            return false;
        }
    }
}

