public class FactoryChecker {

    // Rule did not trigger both before and after the change
    public boolean isFactoryMethodA(String qualifier, String name) {
        if (qualifier != null) {
            return typeEndsWith(qualifier, "Factory")
                || nameEndsWith(name);
        }
        return false;
    }

    // NEW BEHAVIOUR - Rule no longer triggers here though it previously did
    public boolean isFactoryMethodB(String qualifier, String name) {
        if (qualifier != null) {
            return (typeEndsWith(qualifier, "Factory")
                || nameEndsWith(name));
        }
        return false;
    }

    private boolean typeEndsWith(String q, String suffix) { return q != null && q.endsWith(suffix); }
    private boolean nameEndsWith(String n) { return n != null && n.endsWith("Factory"); }
}

import java.util.List;
import java.util.Set;
import java.util.function.Predicate;

class Foo {
    boolean hasResults(Build lastCompletedBuild, boolean selectTools, Set<String> tools) {
        if (lastCompletedBuild == null) {
            return true;
        }
        return lastCompletedBuild.getActions(ResultAction.class)
                .stream()
                .filter(createToolFilter(selectTools, tools))
                .anyMatch(resultAction -> resultAction.getResult().getTotalSize() > 0);
    }

    Predicate<ResultAction> createToolFilter(boolean selectTools, Set<String> tools) {
        return action -> !selectTools || tools.contains(action.getTool());
    }

    interface Build { List<ResultAction> getActions(Class<ResultAction> type); }
    interface ResultAction {
        Result getResult();
        String getTool();
    }
    interface Result { int getTotalSize(); }
}

import java.util.stream.Stream;

class Foo {
    boolean literalThenTrue(boolean guard, Stream<String> values) {
        if (guard) return true;
        return values.anyMatch(value -> value == null);
    }

    boolean literalElseFalse(boolean guard, Stream<String> values) {
        if (guard) {
            return values.anyMatch(value -> value == null);
        } else {
            return false;
        }
    }
}

import java.util.stream.Stream;

class Foo {
    boolean literalThenFalse(boolean guard, Stream<String> values) {
        if (guard) {
            return false;
        } else {
            return values.anyMatch(value -> { return value == null; });
        }
    }

    boolean literalElseTrue(boolean guard, Stream<String> values) {
        if (guard) return values.anyMatch(value -> { return value == null; });
        return true;
    }
}

