        if (guard) {
            return value.trim().isEmpty();
        } else {
            return false;
        }
    }

    boolean literalElseTrue(boolean guard, String value) {
        if (guard) return value.trim().isEmpty();
        return true;
    }

    boolean literalThenTrue(boolean guard, String value) {
        if (guard) {
            return true;
        }
        return value.trim().isEmpty();
    }

    boolean literalThenFalse(boolean guard, String value) {
        if (guard) return false;
        else return value.trim().isEmpty();
    }
}

