class Foo {
    boolean hasEmptyValue(boolean guard, List<String> values) {
        if (guard) return false;
        return values.stream().map(String::trim).anyMatch(String::isEmpty);
    }
}

import java.util.List;
import java.util.stream.Stream;

class Foo {
    boolean oneCall(boolean guard, Stream<String> values) {
        if (guard) return values.anyMatch(String::isEmpty);
        else return true;
    }

    boolean twoCalls(boolean guard, List<String> values) {
        if (guard) return false;
        return values.stream().anyMatch(String::isEmpty);
    }
}

class Foo {
    boolean parenthesized(boolean guard, String value) {
        if (guard) return (value.trim().toLowerCase().isEmpty());
        return false;
    }

    boolean negated(boolean guard, String value) {
        if (guard) {
            return true;
        } else {
            return !value.trim().toLowerCase().isEmpty();
        }
    }
}

class Foo {
    boolean cast(boolean guard, String value) {
        if (guard) return false;
        return (boolean) value.trim().toLowerCase().isEmpty();
    }

    boolean comparison(boolean guard, String value) {
        if (guard) {
            return value.trim().toLowerCase().length() == 0;
        } else {
            return true;
        }
    }
}

class Foo {
    boolean twoCalls(boolean guard, boolean flag, String value) {
        if (guard) return Boolean.logicalAnd(flag, value.isEmpty());
        return false;
    }

    boolean threeCallsInSiblingArguments(boolean guard, String left, String right) {
        if (guard) return true;
        return Boolean.logicalAnd(left.isEmpty(), right.isEmpty());
    }

    boolean threeCallsInNestedArguments(boolean guard, boolean flag, String value) {
        if (guard) return Boolean.logicalAnd(flag, Boolean.logicalOr(flag, value.isEmpty()));
        else return true;
    }
}

import java.util.List;

class Foo {
    boolean trueThenFalse(List<String> values) {
        if (values.stream().filter(String::isEmpty).anyMatch(value -> value == null)) {
            return true;
        } else {
            return false;
        }
    }

    boolean falseThenTrue(List<String> values) {
        if (values.stream().filter(String::isEmpty).anyMatch(value -> value == null)) return false;
        return true;
    }

    boolean bothTrue(List<String> values) {
        if (values.stream().filter(String::isEmpty).anyMatch(value -> value == null)) return true;
        else return true;
    }

    boolean bothFalse(List<String> values) {
        if (values.stream().filter(String::isEmpty).anyMatch(value -> value == null)) {
            return false;
        }
        return false;
    }
}

import java.util.List;

class Foo {
    boolean literalThen(List<String> values, boolean fallback) {
        if (values.stream().filter(String::isEmpty).anyMatch(value -> value == null)) return true;
        return fallback;
    }

    boolean literalElse(List<String> values, String fallback) {
        if (values.stream().filter(String::isEmpty).anyMatch(value -> value == null)) {
            return fallback.isEmpty();
        } else {
            return false;
        }
    }
}

class Foo {
    boolean complement(boolean guard, String value) {
        if (guard) return value.trim().toLowerCase().isEmpty();
        return !value.trim().toLowerCase().isEmpty();
    }
}

class Foo {
    boolean literalThenTrue(boolean guard, String value) {
        if (guard) return true;
        return value.isEmpty();
    }

    boolean literalThenFalse(boolean guard, String value) {
        if (guard) return false;
        else return value.isEmpty();
    }

    boolean literalElseTrue(boolean guard, String value) {
        if (guard) return value.isEmpty();
        return true;
    }

    boolean literalElseFalse(boolean guard, String value) {
        if (guard) return value.isEmpty();
        else return false;
    }
}

class Foo {
    boolean literalThenTrue(boolean guard, boolean choose, boolean left, boolean right) {
        if (guard) return true;
        return choose ? left : right;
    }

    boolean literalThenFalse(boolean guard, boolean choose, boolean left, boolean right) {
        if (guard) return false;
        else return (choose ? left : right);
    }

    boolean literalElseTrue(boolean guard, boolean choose, boolean left, boolean right) {
        if (guard) return choose ? left : right;
        return true;
    }

    boolean literalElseFalse(boolean guard, boolean choose, boolean left, boolean right) {
        if (guard) return (choose ? left : right);
        else return false;
    }
}

import java.util.stream.Stream;

class Foo {
    boolean negatedThen(boolean guard, String value) {
        if (guard) return !(value.trim().toLowerCase().isEmpty());
        else return true;
    }

    boolean negatedFollowingReturn(boolean guard, String value) {
        if (guard) return false;
        return !value.trim().toLowerCase().isEmpty();
    }

    boolean negatedLambdaThen(boolean guard, Stream<String> values) {
        if (guard) return !values.anyMatch(value -> value == null);
        return false;
    }

    boolean negatedLambdaElse(boolean guard, Stream<String> values) {
        if (guard) return true;
        else return !values.anyMatch(value -> { return value == null; });
    }
}

import java.util.Set;

class Foo {
    private static final Set<String> TRUE_STRINGS = Set.of("true", "on", "yes", "1");
    private static final Set<String> FALSE_STRINGS = Set.of("false", "off", "no", "0");

    boolean toBool(String stringToConvert, boolean defaultValue) {
        if (stringToConvert.isEmpty()) {
            return defaultValue;
        } else if (TRUE_STRINGS.contains(stringToConvert)) {
            return true;
        } else if (FALSE_STRINGS.contains(stringToConvert)) {
            return false;
        } else {
            return defaultValue;
        }
    }
}

import java.util.List;

class Foo {
    boolean toBool(List<String> values, boolean defaultValue) {
        if (values.isEmpty()) {
            return defaultValue;
        } else if (values.size() == 1) {
            return true;
        } else if (values.get(0).isEmpty()) {
            return false;
        } else {
            return values.stream().map(String::trim).anyMatch(String::isEmpty);
        }
    }
}

